/**
 * Msg defines the alias Msg service.
 *
 * There is no MsgSetAlias, because identifiers are assigned rather than chosen:
 * a chosen handle brings squatting, a resale market, and — the one that costs
 * money — impersonation, where YAMALE-PAY and YAMALE-PAY1 look identical in a
 * confirmation dialog.
 *
 * There is no MsgReleaseAlias either. Releasing and re-registering as two
 * messages would leave an account unreachable between them, so rotation is one
 * atomic message.
 *
 * There is no MsgClearJurisdiction. Removing a country would put an account
 * back into the unclaimed state the perimeter exists to abolish, holding an
 * identifier whose prefix names a country the chain no longer records. A
 * jurisdiction is corrected, never emptied.
 */
export interface Msg {
  /** RegisterAlias issues an identifier to the sending account. */
  RegisterAlias(request: MsgRegisterAlias): Promise<MsgRegisterAliasResponse>;
  /** RotateAlias retires the sender's identifier and issues a new one. */
  RotateAlias(request: MsgRotateAlias): Promise<MsgRotateAliasResponse>;
  /** SetJurisdiction records or corrects the country an account belongs to. */
  SetJurisdiction(request: MsgSetJurisdiction): Promise<MsgSetJurisdictionResponse>;
  /** RegisterViewingKey publishes the sender's X25519 public key, or rotates it. */
  RegisterViewingKey(request: MsgRegisterViewingKey): Promise<MsgRegisterViewingKeyResponse>;
  /** RevokeViewingKey marks one of the sender's key versions compromised. */
  RevokeViewingKey(request: MsgRevokeViewingKey): Promise<MsgRevokeViewingKeyResponse>;
  /** AppointRegulator names the authority holding the viewing key for a country. */
  AppointRegulator(request: MsgAppointRegulator): Promise<MsgAppointRegulatorResponse>;
  /** GrantAuditor grants the time-boxed cross-account reading role. */
  GrantAuditor(request: MsgGrantAuditor): Promise<MsgGrantAuditorResponse>;
  /**
   * GrantRole grants a role inside one jurisdiction. Governance, or the
   * foundation for a country; governance alone for the chain-wide scope.
   */
  GrantRole(request: MsgGrantRole): Promise<MsgGrantRoleResponse>;
  /** RevokeRole removes one such grant. The same signers as GrantRole. */
  RevokeRole(request: MsgRevokeRole): Promise<MsgRevokeRoleResponse>;
  /**
   * UpdateParams sets the module parameters. Governance only, and it is the only
   * way a foundation administrator is appointed or removed — the foundation's own
   * M-of-N group cannot do it, and nothing else can either.
   *
   * It REPLACES THE WHOLE Params OBJECT. `params` is a message, not a field mask,
   * and there is no partial update, so "appoint one administrator" means reading
   * the current parameters, adding one address, and resubmitting every parameter.
   * A proposal composed without reading them first passes and silently drops the
   * administrators already appointed, or resets payload_length. Nothing catches
   * that: a list shorter than the one before it is a valid list.
   *
   * A payload_length that reads back as 0 means the value is UNKNOWN, not zero —
   * proto3 cannot tell a zero from a field nobody filled in, and Validate()
   * refuses a zero, so no chain holds one. Resubmitting a guess would
   * re-parameterise the chain while reading as an appointment.
   *
   * Note also what Validate() does NOT check: that an entry in
   * foundation_administrators is an address. A mistyped one passes a governance
   * vote, occupies one of the eight capped places, and grants the exemption to
   * nobody. Verify the bech32 checksum before composing; the chain will not.
   */
  UpdateParams(request: MsgUpdateParams): Promise<MsgUpdateParamsResponse>;
}

